import unittest
from unittest.mock import patch

from cache_middleware import cache_response, _build_cache_key

# Mock the Redis client for testing
mock_redis = patch('cache_middleware.redis.Redis')

class TestCacheMiddleware(unittest.TestCase):

    @mock_redis.enter
    def test_cache_hit(self):
        mock_redis_client = mock_redis.return_value
        mock_redis_client.get.return_value = b"Cached response"

        @cache_response(cache_duration=10)
        def my_function(a, b):
            return f"Result: {a} + {b}"

        response = my_function(1, 2)
        self.assertEqual(response, "Cached response")
        mock_redis_client.set.assert_not_called()  

